"""Build the shipment summary described in /app/docs/summary-format.md.

Usage: python3 summarize.py DATA_DIR OUT_FILE
"""
import csv
import datetime as dt
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

KG = {"kg": Decimal("1"), "g": Decimal("0.001"), "lb": Decimal("0.45392"),
      "oz": Decimal("0.02837")}
UNIT_ALIASES = {"kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg",
                "g": "g", "gr": "g", "gram": "g", "grams": "g",
                "lb": "lb", "lbs": "lb", "pound": "lb", "pounds": "lb",
                "oz": "oz", "ounce": "oz", "ounces": "oz"}
DEPOT_ORDER = ["central", "south", "east", "river", "north", "west", "harbor",
               "lakeside"]
COUNTED = {"delivered", "delivered_late"}
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct",
     "nov", "dec"])}

# ---------------------------------------------------------------- helpers


def norm_unit(s):
    if s is None:
        return None
    s = str(s).strip().lower()
    m = re.match(r"[a-z]+", s)
    if not m:
        return None
    return UNIT_ALIASES.get(m.group(0))


def norm_status(s):
    s = (s or "").strip().lower()
    return re.sub(r"[\s_-]+", "_", s)


STATUS_CODES = {"dlv": "delivered", "dll": "delivered_late",
                "can": "cancelled", "ret": "returned", "hld": "held"}


def norm_type(s):
    s = (s or "").strip().lower()
    if s in ("", "n", "new"):
        return "new"
    if s in ("c", "cor", "corr", "correction", "amend", "amendment"):
        return "corr"
    if s in ("v", "void"):
        return "void"
    return "new"


def shipment_number(s):
    if s is None:
        return None
    m = re.match(r"^\s*sh\D*(\d+)\s*$", str(s), re.I)
    if not m:
        return None
    return int(m.group(1))


def parse_number(text, decimal_comma=False):
    """Return (Decimal, unit-or-None) from a weight text, or (None, None)."""
    if text is None:
        return None, None
    if isinstance(text, Decimal):
        return text, None
    if isinstance(text, (int, float)):
        return Decimal(str(text)), None
    s = str(text).strip()
    m = re.match(r"^([+-]?[\d.,\s]*\d)\s*([A-Za-z]+)?$", s)
    if not m:
        return None, None
    num = re.sub(r"\s", "", m.group(1))
    unit = norm_unit(m.group(2)) if m.group(2) else None
    if decimal_comma:
        num = num.replace(".", "").replace(",", ".")
    else:
        num = num.replace(",", "")
    try:
        return Decimal(num), unit
    except InvalidOperation:
        return None, None


# ---------------------------------------------------------------- dates


def parse_date(value, form=None):
    """Parse a date (no time of day) in the given form; return a date."""
    v = (value or "").strip()
    if not v:
        return None
    # month names: 16 Mar 2026
    m = re.match(r"^(\d{1,2})[\s-]+([A-Za-z]{3})[A-Za-z]*\.?,?[\s-]+(\d{4})$", v)
    if m and m.group(2).lower() in MONTHS:
        return dt.date(int(m.group(3)), MONTHS[m.group(2).lower()],
                       int(m.group(1)))
    f = re.sub(r"[\s_]", "", (form or "").lower())
    base = dt.date(1899, 12, 30)
    try:
        if f == "serial":
            return base + dt.timedelta(days=int(Decimal(v)))
        if f == "yyyyddd":
            return dt.date(int(v[:4]), 1, 1) + dt.timedelta(days=int(v[4:7]) - 1)
        if f == "yyyymmdd":
            return dt.date(int(v[:4]), int(v[4:6]), int(v[6:8]))
        parts = re.split(r"\D+", v)
        parts = [p for p in parts if p]
        if f in ("dmy", "dd/mm/yyyy", "dd.mm.yyyy", "dd-mm-yyyy") and len(parts) == 3:
            return dt.date(int(parts[2]), int(parts[1]), int(parts[0]))
        if f in ("mdy", "mm/dd/yyyy", "mm-dd-yyyy") and len(parts) == 3:
            return dt.date(int(parts[2]), int(parts[0]), int(parts[1]))
        if f in ("iso", "ymd", "yyyy-mm-dd", "yyyy/mm/dd") and len(parts) == 3:
            return dt.date(int(parts[0]), int(parts[1]), int(parts[2]))
    except (ValueError, OverflowError, InvalidOperation):
        pass
    # fall back on the shape of the value
    try:
        if re.fullmatch(r"\d{7}", v):
            return dt.date(int(v[:4]), 1, 1) + dt.timedelta(days=int(v[4:]) - 1)
        if re.fullmatch(r"\d{8}", v):
            return dt.date(int(v[:4]), int(v[4:6]), int(v[6:]))
        if re.fullmatch(r"\d{4}\D\d{1,2}\D\d{1,2}", v):
            p = re.split(r"\D", v)
            return dt.date(int(p[0]), int(p[1]), int(p[2]))
        if re.fullmatch(r"\d{5}(\.\d+)?", v):
            return base + dt.timedelta(days=int(Decimal(v)))
    except (ValueError, OverflowError, InvalidOperation):
        pass
    return None


def parse_ship(value, form=None):
    """Return the UTC calendar date (as a date) of a ship date / time."""
    if value is None:
        return None
    v = str(value).strip()
    if not v:
        return None
    if re.search(r"\d[T ]\d{1,2}:\d{2}", v) or re.search(r"\dT\d{2}", v):
        s = v
        s = re.sub(r"\s*(UTC|GMT)$", "Z", s)
        s = re.sub(r"^(\d{4}-\d{2}-\d{2}) (?=\d)", r"\1T", s)
        s = re.sub(r"\s+([+-]\d{2}(:?\d{2})?)$", r"\1", s)
        try:
            d = dt.datetime.fromisoformat(s)
        except ValueError:
            m = re.match(r"^(\d{4}-\d{2}-\d{2})", s)
            if not m:
                return None
            return parse_date(m.group(1), "iso")
        if d.tzinfo is not None:
            d = d.astimezone(dt.timezone.utc)
        return d.date()
    return parse_date(v, form)


# ---------------------------------------------------------------- decoding


def read_bytes(path):
    with open(path, "rb") as fh:
        b = fh.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", errors="replace")
    if b[:2] == b"\xff\xfe":
        return b[2:].decode("utf-16-le", errors="replace")
    if b[:2] == b"\xfe\xff":
        return b[2:].decode("utf-16-be", errors="replace")
    head = b[:4096]
    for line in head.split(b"\n")[:30]:
        m = re.match(rb"^#\s*charset\s*:\s*([A-Za-z0-9_.:-]+)", line)
        if m:
            try:
                return b.decode(m.group(1).decode("ascii"), errors="replace")
            except LookupError:
                break
    try:
        return b.decode("utf-8")
    except UnicodeDecodeError:
        return b.decode("utf-8", errors="replace")


def split_lines(text):
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    return [l[:-1] if l.endswith("\r") else l for l in lines]


# ---------------------------------------------------------------- records
# A record is a dict: num, type, month (date or None), kg (Decimal), counted.


def make_record(num, typ, ship_date, weight, unit, status):
    rec = {"num": num, "type": typ}
    if typ == "void":
        return rec
    kg = None
    if weight is not None:
        kg = weight * KG[unit or "kg"]
    rec["kg"] = kg if kg is not None else Decimal(0)
    rec["date"] = ship_date
    rec["counted"] = norm_status(status) in COUNTED
    return rec


class Export:
    def __init__(self, depot, name):
        self.depot = depot
        self.name = name
        self.seq = None
        self.records = []


SEQ_RE = re.compile(r"\bseq\b\s*[:=]?\s*(\d+)", re.I)


def note_seq(exp, comment):
    if exp.seq is None:
        m = SEQ_RE.search(comment)
        if m:
            exp.seq = int(m.group(1))


DIRECTIVE_RE = re.compile(r"^#\s*([^:=#]+?)\s*:\s*(.*?)\s*$")
UNIT_NAMES = {"unit", "units", "weight unit", "weight-unit", "weightunit"}
DATE_NAMES = {"dates", "date", "date format", "date-format", "dateformat",
              "date form"}

DELIMITED = {
    "east": dict(delim=",", quoted=True, cols=["id", "type", "shipped", "gross",
                 "net", "status", "note"], decimal_comma=False),
    "lakeside": dict(delim=",", quoted=True, cols=["id", "kind", "booked",
                     "shipped", "gross_kg", "net_kg", "status"],
                     decimal_comma=False),
    "river": dict(delim="\t", quoted=False, cols=["t", "ref", "shipped",
                  "weight", "status"], decimal_comma=False),
    "west": dict(delim=";", quoted=False, cols=["id", "typ", "shipped",
                 "weight", "status", "note"], decimal_comma=True),
    "harbor": dict(delim="|", quoted=False, cols=["rec", "ref", "date",
                   "weight", "state"], decimal_comma=False),
}
BASE_DATE = {"east": "YMD", "lakeside": "iso", "river": "MM/DD/YYYY",
             "west": "DD.MM.YYYY", "harbor": "iso"}
EXTRA_COLS = {"lakeside": ["gross_g", "gross_lb", "gross_oz", "net_g", "net_lb",
                           "net_oz", "gross", "net"],
              "harbor": [], "east": [], "river": [], "west": []}
ID_COLS = ("id", "ref")
TYPE_COLS = ("type", "kind", "typ", "t", "rec")
DATE_COLS = ("shipped", "date", "shipped_at")
STATUS_COLS = ("status", "state")


def split_rows(text, cfg):
    """Yield ('comment', line) or ('row', fields) in file order."""
    lines = split_lines(text)
    buf = None
    for line in lines:
        if buf is None:
            if line.startswith("#"):
                yield "comment", line
                continue
            if not line.strip():
                continue
            buf = line
        else:
            buf = buf + "\n" + line
        if cfg["quoted"]:
            if buf.count('"') % 2 == 1:
                continue
            try:
                row = next(csv.reader(io.StringIO(buf, newline="")))
            except (csv.Error, StopIteration):
                row = [buf]
        else:
            row = buf.split(cfg["delim"])
        buf = None
        yield "row", row
    if buf is not None and cfg["quoted"]:
        try:
            yield "row", next(csv.reader(io.StringIO(buf, newline="")))
        except (csv.Error, StopIteration):
            pass


def weight_col(header):
    for i, h in enumerate(header):
        if h in ("gross", "weight", "weight_kg", "gross_kg", "gross_g",
                 "gross_lb", "gross_oz", "weight_g", "weight_lb", "weight_oz"):
            return i
    return None


def parse_delimited(depot, text, exp):
    cfg = DELIMITED[depot]
    known = set(cfg["cols"]) | set(EXTRA_COLS.get(depot, []))
    header = list(cfg["cols"])
    unit_dir = None
    date_form = BASE_DATE[depot]
    for kind, item in split_rows(text, cfg):
        if kind == "comment":
            note_seq(exp, item)
            m = DIRECTIVE_RE.match(item)
            if m:
                name = re.sub(r"\s+", " ", m.group(1).lower())
                val = m.group(2)
                if name in UNIT_NAMES:
                    unit_dir = norm_unit(val) or unit_dir
                elif name in DATE_NAMES:
                    date_form = val.strip() or date_form
            continue
        row = item
        names = [f.strip().lower() for f in row]
        if all(n in known for n in names):
            header = names
            continue
        idx = {h: i for i, h in enumerate(header)}
        wi = weight_col(header)
        row_unit = None
        if len(row) == len(header) + 1 and wi is not None:
            ui = None
            if wi + 1 < len(row) and norm_unit(row[wi + 1]) and \
                    row[wi + 1].strip().isalpha():
                ui = wi + 1
            else:
                for j in range(len(row)):
                    if row[j].strip().lower() in UNIT_ALIASES:
                        ui = j
                        if j > wi:
                            break
            if ui is not None:
                row_unit = norm_unit(row[ui])
                row = row[:ui] + row[ui + 1:]
        if len(row) < len(header):
            row = row + [""] * (len(header) - len(row))

        def get(cols):
            for c in cols:
                if c in idx and idx[c] < len(row):
                    return row[idx[c]].strip()
            return ""

        num = shipment_number(get(ID_COLS))
        if num is None:
            continue
        typ = norm_type(get(TYPE_COLS))
        if typ == "void":
            exp.records.append(make_record(num, "void", None, None, None, None))
            continue
        # weight, with its unit
        wtext = None
        field_unit = None
        wname = None
        for c in header:
            if c in ("gross", "weight") or re.fullmatch(r"(gross|weight)_(kg|g|lb|oz)", c):
                wname = c
                break
        if wname is not None:
            wtext = row[idx[wname]] if idx[wname] < len(row) else ""
            m = re.fullmatch(r"(?:gross|weight)_(kg|g|lb|oz)", wname)
            if m:
                field_unit = m.group(1)
        w, text_unit = parse_number(wtext, cfg["decimal_comma"])
        unit = text_unit or field_unit or row_unit or unit_dir or "kg"
        status = get(STATUS_COLS)
        if depot == "harbor":
            status = STATUS_CODES.get(status.strip().lower(), status)
        ship = parse_ship(get(DATE_COLS), date_form)
        exp.records.append(make_record(num, typ, ship, w, unit, status))


# ---------------------------------------------------------------- JSON lines


def parse_north(text, exp):
    for line in split_lines(text):
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        try:
            obj = json.loads(s, parse_float=Decimal, parse_int=Decimal)
        except ValueError:
            continue
        objs = obj if isinstance(obj, list) else [obj]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if exp.seq is None and "seq" in o["meta"]:
                    try:
                        exp.seq = int(o["meta"]["seq"])
                    except (TypeError, ValueError):
                        pass
                continue
            num = shipment_number(o.get("id"))
            if num is None:
                continue
            typ = norm_type(o.get("kind"))
            if typ == "void":
                exp.records.append(make_record(num, "void", None, None, None, None))
                continue
            w = unit = None
            for k, v in o.items():
                m = re.fullmatch(r"weight_(kg|g|lb|oz)", k.lower())
                if m:
                    w, tu = parse_number(v)
                    unit = tu or m.group(1)
                    break
            if w is None and "weight" in o:
                w, tu = parse_number(o["weight"])
                unit = tu or norm_unit(o.get("unit") or o.get("weight_unit")) or "kg"
            ship = parse_ship(o.get("shipped_at") or o.get("shipped"), "iso")
            exp.records.append(make_record(num, typ, ship, w, unit,
                                           str(o.get("status", ""))))


# ---------------------------------------------------------------- XML


def parse_central(raw, text, exp):
    if raw[:3] == b"\xef\xbb\xbf" or raw[:2] in (b"\xff\xfe", b"\xfe\xff"):
        root = ET.fromstring(text)
    else:
        root = ET.fromstring(raw)
    if root.get("seq") is not None:
        try:
            exp.seq = int(root.get("seq"))
        except ValueError:
            pass
    root_unit = norm_unit(root.get("weight-unit") or root.get("weight_unit")
                          or root.get("unit"))

    def getv(e, name):
        c = e.find(name)
        if c is not None:
            return c.text or ""
        v = e.get(name)
        return v if v is not None else None

    for e in root.iter("shipment"):
        num = shipment_number(e.get("id") if e.get("id") is not None
                              else getv(e, "id"))
        if num is None:
            continue
        typ = norm_type(e.get("type"))
        if typ == "void":
            exp.records.append(make_record(num, "void", None, None, None, None))
            continue
        wel = e.find("weight")
        wtext = wel.text if wel is not None else e.get("weight")
        w, tu = parse_number(wtext)
        unit = None
        if wel is not None:
            unit = norm_unit(wel.get("unit"))
        unit = (tu or unit
                or norm_unit(e.get("weight-unit") or e.get("unit"))
                or root_unit or "kg")
        ship = parse_ship(getv(e, "shipped"), "iso")
        exp.records.append(make_record(num, typ, ship, w, unit,
                                       getv(e, "status") or ""))


# ---------------------------------------------------------------- fixed width

LAYOUTS = {
    "FW1": dict(length=42, id=(0, 9), type=(9, 10), shipped=(10, 17),
                weight=(17, 25), status=(25, 26), date="yyyyddd",
                unit="g", scale=Decimal(1)),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), shipped=(10, 18),
                weight=(18, 26), status=(26, 27), date="yyyymmdd",
                unit="kg", scale=Decimal("0.01")),
    "FW3": dict(length=41, id=(0, 9), shipped=(9, 16), type=(16, 17),
                weight=(17, 24), status=(24, 25), date="yyyyddd",
                unit="lb", scale=Decimal("0.1")),
}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}


def parse_south(text, exp):
    layout = None
    by_len = {v["length"]: k for k, v in LAYOUTS.items()}
    for line in split_lines(text):
        if line.startswith("\x0c") or "SHIPMENT LISTING" in line:
            continue
        if line.startswith("#"):
            m = re.match(r"^#\s*LAYOUT\s+(\S+)", line, re.I)
            if m and m.group(1).upper() in LAYOUTS:
                layout = m.group(1).upper()
            note_seq(exp, line)
            continue
        if not line.strip():
            continue
        name = by_len.get(len(line))
        if name is None:
            name = layout
            if name is None:
                continue
            line = line.ljust(LAYOUTS[name]["length"])
        L = LAYOUTS[name]
        num = shipment_number(line[slice(*L["id"])])
        if num is None:
            continue
        typ = norm_type(line[slice(*L["type"])])
        if typ == "void":
            exp.records.append(make_record(num, "void", None, None, None, None))
            continue
        ship = parse_date(line[slice(*L["shipped"])], L["date"])
        wtxt = line[slice(*L["weight"])].strip()
        try:
            w = Decimal(wtxt) * L["scale"]
        except InvalidOperation:
            w = None
        status = FW_STATUS.get(line[slice(*L["status"])].strip().upper(), "")
        exp.records.append(make_record(num, typ, ship, w, L["unit"], status))


# ---------------------------------------------------------------- driver


def load_export(path, depot, name):
    raw = read_bytes(path)
    text = decode(raw)
    exp = Export(depot, name)
    d = depot.lower()
    if d in DELIMITED:
        parse_delimited(d, text, exp)
    elif d == "north":
        parse_north(text, exp)
    elif d == "central":
        parse_central(raw, text, exp)
    elif d == "south":
        parse_south(text, exp)
    else:
        raise ValueError("unknown depot " + depot)
    return exp


def rank(depot):
    d = depot.lower()
    return DEPOT_ORDER.index(d) if d in DEPOT_ORDER else len(DEPOT_ORDER)


def q2(x):
    return float(x.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def summarize(data_dir):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        exports.setdefault(depot, [])
        try:
            exports[depot].append(load_export(path, depot, name))
        except Exception as e:  # keep going; report on stderr
            print("warning: cannot read %s: %s" % (name, e), file=sys.stderr)

    corrections = resends = 0
    current = {}
    for depot, exps in exports.items():
        exps.sort(key=lambda e: (e.seq if e.seq is not None else -1, e.name))
        cur = {}
        for exp in exps:
            for r in exp.records:
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "corr":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    owners = {}
    for depot, cur in current.items():
        for n in cur:
            owners.setdefault(n, []).append(depot)
    handovers = 0
    kept = {}
    for n, deps in owners.items():
        if len(deps) > 1:
            handovers += 1
        deps.sort(key=lambda d: (rank(d), d))
        kept[n] = (deps[0], current[deps[0]][n])

    dep_tot = {d: [0, Decimal(0)] for d in exports}
    mon_tot = {}
    for n, (depot, r) in kept.items():
        if not r["counted"]:
            continue
        dep_tot[depot][0] += 1
        dep_tot[depot][1] += r["kg"]
        if r["date"] is not None:
            key = "%04d-%02d" % (r["date"].year, r["date"].month)
            t = mon_tot.setdefault(key, [0, Decimal(0)])
            t[0] += 1
            t[1] += r["kg"]

    return {
        "depots": {d: {"shipments": dep_tot[d][0], "total_kg": q2(dep_tot[d][1])}
                   for d in sorted(dep_tot)},
        "months": {k: {"shipments": mon_tot[k][0], "total_kg": q2(mon_tot[k][1])}
                   for k in sorted(mon_tot)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }


def main(argv):
    if len(argv) != 3:
        print("usage: summarize.py DATA_DIR OUT_FILE", file=sys.stderr)
        return 2
    result = summarize(argv[1])
    out = argv[2]
    d = os.path.dirname(out)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(out, "w", encoding="utf-8") as fh:
        json.dump(result, fh, indent=2)
        fh.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
"}

